<?php
declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';
if($_SERVER['REQUEST_METHOD']==='GET'){$slug=slugify($_GET['slug']??'');$viewer=currentUser($pdo);$q=$pdo->prepare('SELECT COALESCE(SUM(count),0) FROM claps WHERE post_slug=?');$q->execute([$slug]);$claps=(int)$q->fetchColumn();$comments=$pdo->prepare("SELECT COUNT(*) FROM comments WHERE post_slug=? AND status='visible'");$comments->execute([$slug]);$saved=false;$myClaps=0;if($viewer){$q=$pdo->prepare('SELECT 1 FROM bookmarks WHERE user_id=? AND post_slug=?');$q->execute([$viewer['id'],$slug]);$saved=(bool)$q->fetchColumn();$q=$pdo->prepare('SELECT count FROM claps WHERE user_id=? AND post_slug=?');$q->execute([$viewer['id'],$slug]);$myClaps=(int)($q->fetchColumn()?:0);}exit(json_encode(['claps'=>$claps,'comments'=>(int)$comments->fetchColumn(),'saved'=>$saved,'my_claps'=>$myClaps]));}
$user=requireUser($pdo);$d=input();$action=$d['action']??'';$slug=slugify($d['slug']??'');if(!$slug){http_response_code(422);exit(json_encode(['error'=>'Story required.']));}
if($action==='clap'){$q=$pdo->prepare('INSERT INTO claps(user_id,post_slug,count) VALUES(?,?,1) ON DUPLICATE KEY UPDATE count=LEAST(count+1,50)');$q->execute([$user['id'],$slug]);exit(json_encode(['ok'=>true]));}
if($action==='bookmark'){$q=$pdo->prepare('SELECT 1 FROM bookmarks WHERE user_id=? AND post_slug=?');$q->execute([$user['id'],$slug]);if($q->fetchColumn()){$q=$pdo->prepare('DELETE FROM bookmarks WHERE user_id=? AND post_slug=?');$q->execute([$user['id'],$slug]);$saved=false;}else{$q=$pdo->prepare('INSERT INTO bookmarks(user_id,post_slug) VALUES(?,?)');$q->execute([$user['id'],$slug]);$saved=true;}exit(json_encode(['ok'=>true,'saved'=>$saved]));}
http_response_code(422);echo json_encode(['error'=>'Unknown action.']);
